<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { app, gs, game, close, open, setMode, setEditing, summon, setShared, hands, stage, setTool, toggleTorch, saveNow, toast, gather, populateNow, selectToken } from '../session'
import { MONSTERS } from '../rules/monsters'
import { crText } from '../rules/base'
import { models } from '../core/catalog'
import MonThumb from './MonThumb.vue'
const q = ref(''), i = ref(0), box = ref<HTMLInputElement>(); onMounted(() => nextTick(() => box.value?.focus())); const dm = app.role === 'dm'; interface C { t: string; s?: string; icon?: string; mon?: string; go: () => void }
const all = computed<C[]>(() => { const G = gs.value, L: C[] = [{ t: 'Isometric view', icon: 'cube', go: () => setMode('iso') }, { t: 'Top-down view', icon: 'treasure-map', go: () => setMode('top') }, ...(dm ? [{ t: 'Fly', icon: 'feathered-wing', go: () => setMode('fly') }] : [{ t: 'First person', icon: 'eye-shield', go: () => setMode('fps') }, { t: 'Third person', icon: 'walk', go: () => setMode('tps') }]), { t: 'Journal', icon: 'open-book', go: () => open('journal') }, { t: 'Settings', icon: 'cog', go: () => open('settings') }, { t: 'Keys', icon: 'key', go: () => open('keys') }, { t: 'Torch', icon: 'torch', go: toggleTorch }]; if (app.seat) L.push({ t: 'Character sheet', icon: 'character', go: () => open('sheet') }, { t: 'Spellbook', icon: 'spell-book', go: () => open('sheet', 'spells') }, { t: 'Pack', icon: 'knapsack', go: () => open('sheet', 'pack') }); if (app.hosting) L.push({ t: 'Invite players', icon: 'entry-door', go: () => open('invite') }, { t: 'Save now', icon: 'save', go: () => saveNow().then(() => toast('Saved.')) }); if (dm) { L.push({ t: 'Build', s: 'B', icon: 'anvil', go: () => setEditing(!app.editing) }, { t: app.shared.fog ? 'Fog of war off' : 'Fog of war on', icon: 'fog', go: () => setShared({ fog: !app.shared.fog }) }, { t: app.shared.paused ? 'Resume' : 'Pause the game', icon: 'pause-button', go: () => setShared({ paused: !app.shared.paused }) }, { t: 'Gather the heroes here', icon: 'backup', go: gather }, { t: 'Populate every room', icon: 'dungeon-gate', go: () => populateNow({}) }, { t: 'Short rest for the party', icon: 'campfire', go: () => hands('rest', { kind: 'short' }) }, { t: 'Long rest for the party', icon: 'night-sleep', go: () => hands('rest', { kind: 'long' }) }, { t: 'Start a fight with what is in sight', icon: 'crossed-swords', go: () => hands('start_combat') }, { t: 'End the fight', icon: 'peace-dove', go: () => stage?.endFight() }); for (const w of ['clear', 'rain', 'snow', 'fog']) L.push({ t: 'Weather: ' + w, icon: 'sun-cloud', go: () => hands('weather', { to: w }) }); for (const m of MONSTERS) L.push({ t: m.name, s: 'CR ' + crText(m.cr), mon: m.id, go: () => void summon(m.id) }); for (const m of models()) if (!['leaf', 'spiral', 'stairs'].includes(m.fit ?? '')) L.push({ t: m.id.replace(/_/g, ' '), s: 'place', icon: 'wooden-chair', go: () => { setEditing(true); setTool({ tool: 'prop', model: m.id }) } }) } const w = game.value?.world; if (w) { for (const r of w.rooms.values()) if (r.name && (dm || G?.camp?.rooms[r.id])) L.push({ t: r.name, s: 'room', icon: 'doorway', go: () => { if (!game.value!.view.flat) setMode('iso'); game.value!.centerOn(((r.x0 + r.x1) / 2 - 95.5) * 1.5, ((r.z0 + r.z1) / 2 - 95.5) * 1.5, r.l) } }); for (const t of w.tokens.values()) if (dm || !t.hidden) L.push({ t: t.name, s: 'find', icon: 'position-marker', go: () => { selectToken(t.id); if (game.value!.view.flat) game.value!.centerOn(t.x, t.z, game.value!.nav.levelOf(t.x, t.y, t.z)) } }) } return L })
const list = computed(() => { const s = q.value.toLowerCase().trim(); if (!s) return all.value.slice(0, 14); return all.value.map(c => { const t = c.t.toLowerCase(); const k = t === s ? 0 : t.startsWith(s) ? 1 : t.includes(' ' + s) ? 2 : t.includes(s) ? 3 : 9; return { c, k } }).filter(x => x.k < 9).sort((a, b) => a.k - b.k).slice(0, 14).map(x => x.c) }); const run = (c?: C) => { if (!c) return; close(); c.go() }; const key = (e: KeyboardEvent) => { if (e.key === 'ArrowDown') { i.value = Math.min(list.value.length - 1, i.value + 1); e.preventDefault() } if (e.key === 'ArrowUp') { i.value = Math.max(0, i.value - 1); e.preventDefault() } if (e.key === 'Enter') { e.preventDefault(); run(list.value[i.value]) } if (e.key === 'Escape') close() }
</script>
<template><div class="veil pv" @pointerdown.self="close"><section class="modal paper" style="width:560px"><input ref="box" v-model="q" class="pq" placeholder="Find a command, creature, room or thing" aria-label="Find" @input="i = 0" @keydown="key"><div class="pl scroll"><button v-for="(c, k) in list" :key="c.t + k" :class="{ on: k === i }" @click="run(c)" @pointerenter="i = k"><MonThumb v-if="c.mon" :id="c.mon" :size="28" /><span class="grow cut">{{ c.t }}</span><small>{{ c.mon ? 'summon, ' : '' }}{{ c.s }}</small></button><p v-if="!list.length" class="muted" style="padding:14px">Nothing by that name.</p></div></section></div></template>
<style scoped>.pv{place-items:start center;padding-top:11vh}.pq{font:700 27px var(--serif);padding:15px 20px 16px;background:none;border:0;border-bottom:4px solid var(--ink);color:var(--ink);outline:none;width:100%}.pl{max-height:50vh}.pl button{display:flex;align-items:center;gap:12px;width:100%;padding:5px 20px;min-height:40px;border-bottom:1px solid var(--line)}.pl .on{background:var(--spot);color:var(--on-spot)}.pl small{opacity:.7}@media(max-width:700px){.pv{padding-top:0}}</style>
